(* [comment removed for export] *)
Lemma hz_T3 : forall (pcv rax gp tp s11 t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 xs5 xs6 xs7 xs8 xs10 : word) (sp ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 : word)
    (F : bvmap 5 word) (fc : bv 32) (m : mem)
    (spa ff fp lo : Z) (LF : list fframe) (j8 j4 j16 j472 : list byte) (bs4 fbc gap : list cell),
  (pcv = Z_to_bv 64 P_HZ_RET_DEL \/ pcv = ret_pc (Z_to_bv 64 P_HZ_RET_DEL)) ->
  fresh_frame H LF 4 ff fp ->
  rw_cells asegs m (Z.shiftr ff 3 + 2147450880) hz_sh2a ->
  rw_cells asegs m ff (hz_hdr spa ++ [C8 (Z_to_bv 64 AVP_CFGMAKER); C4 (wz 4294967295); CB 4 j4] ++ [CB 16 j16]) ->
  rw_cells asegs m (ff + 544) [CB 472 j472; C8 (Z_to_bv 64 fp)] ->
  rw_cells asegs m fp [C1 (b8 1)] ->
  rw_cells asegs m spa [CB 8 j8; C8 (Z_to_bv 64 ff)] ->
  rw_cells asegs m (spa + 16) bs4 -> Z.of_nat (cells_size bs4) = 32 ->
  rw_cells asegs m (spa + 48) fbc -> Z.of_nat (cells_size fbc) = 48 ->
  rw_cells asegs m (spa + 96) gap -> Z.of_nat (cells_size gap) = bv_unsigned sp + -96 - (spa + 96) ->
  rw_cells asegs m (bv_unsigned sp + -96) (hz_saved s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra) ->
  stk asegs m lo spa -> (spa = bv_unsigned sp + -192 \/ spa = bv_unsigned sp + -208) -> aceil <= lo -> lo <= spa ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv asegs m -> ACONST m ->
  evt asegs (fun ms' => exists t0' t1' t2' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' m',
         ms' = MS (mkR ra sp gp tp t0' t1' t2' s0 s1 (Z_to_bv 64 0) a1' a2' a3' a4' a5' a6' a7' s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3' t4' t5' t6')
                  F (ret_pc ra) fc None m' (seg_rom asegs)
      /\ munch [(ff, ff + 8); (Z.shiftr ff 3 + 2147450880, Z.shiftr ff 3 + 2147451008); (fp, fp + 1)]%Z m m' /\ wmono asegs m m' /\ mem_inv asegs m'
      /\ stk asegs m' lo (bv_unsigned sp)
      /\ rw_cells asegs m' fp [C1 (b8 0)])
    (MS (mkR rax (Z_to_bv 64 spa) gp tp t0 t1 t2 sp (Z_to_bv 64 spa) a0 a1 a2 a3 a4 a5 a6 a7
             (Z_to_bv 64 ff) (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) (Z_to_bv 64 (-8)) xs5 xs6 xs7 xs8 (Z_to_bv 64 ff) xs10 s11 t3 t4 t5 t6)
